void construct_gossip_message(const ros_etsi_its_msgs::msg::DENM::SharedPtr denm) { 
    struct sockaddr_in server_addr;

    std::cout << "socket_shat----------------------------------" << std::endl;

    // Create a UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) == -1) {
        perror("socket");
        exit(1);
    }

    flatbuffers::FlatBufferBuilder builder;
    std::cout << " ---------------------------------------------------------------------------- " << std::endl;
    std::cout << "Building DENM for station id: " << denm->its_header.station_id << std::endl;
    std::cout << "Building DENM for station id: " << denm->its_header.message_id << std::endl;
    

    // header
    //int32_t trigger_denm = 0;
    ::flatbuffers::Offset<Gos::ItsPduHeader> header = Gos::CreateItsPduHeader(builder, 2, denm->its_header.message_id, denm->its_header.station_id); 
    printf("Is my trigger set properly %u\n", denm->its_header.message_id);
    //::flatbuffers::Offset<Gos::DENMType> denm_type_value = trigger_denm;
    //auto denm_type_value = Gos::DENMType_DENM_REQ_TRIGGER; 
    auto denm_type_value = Gos::DENMType_DENM_REQ_UPDATE;

    // generation time
    //uint64_t gen_del_time = 0; //denm->detection_time; 

    // Create the DENM payload
    //int32_t Gos_DENMType_TYPE_1 = 0;
    auto denm_payload = construct_denm_payload(builder, denm); 
    //Gos_DENMType_enum_t my_denm_type = Gos_DENMType_TYPE_1;
    //auto denm_payload = construct_denm_payload(builder, denm, my_denm_type);

    // Create the DENM message
    struct flatbuffers::Offset<Gos::DENMessage> denm_msg = Gos::CreateDENMessage(builder, header, denm_payload);

    struct flatbuffers::Offset<Gos::DENM> denm_full = Gos::CreateDENM(builder, denm_type_value, denm_msg);


    
    flatbuffers::Offset<void> msgOption = denm_full.Union();
    ::flatbuffers::Offset<FacilityLayerReception> fac_reception_message = CreateFacilityLayerReception(builder, Gos::FacilityLayerMessage_DENM, msgOption); 

    flatbuffers::Offset<void> gossip_option = fac_reception_message.Union();
    ::flatbuffers::Offset<GossipMessage> gossip_msg = CreateGossipMessage(builder, Gos::GossipType::GossipType_FacilityLayerReception, gossip_option);
    builder.Finish(gossip_msg);

    uint8_t* buffer = builder.GetBufferPointer();
    uint64_t size = builder.GetSize();

    // Verify whether the buffer is valid
    flatbuffers::Verifier verifier(buffer, size);
    bool succ = VerifyGossipMessageBuffer(verifier);
    std::cout << "gossip message verified: " << succ << std::endl;
    if (!succ) {
        std::cout << "buffer is invalid" << std::endl;
    } else {
        std::cout << "buffer is valid" << std::endl;
    }
    printf("Total size of the buffer %zu\n", size);

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr(SERVER_ADDR.c_str());  // localhost
    if (sendto(sockfd, buffer, size, 0, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("sendto");
        exit(1);
    } else {
        printf("DENM Information sent to server\n");
    }
    printf("Message sent to the server!\n");
    close(sockfd);
}


::flatbuffers::Offset<Gos::DecentralizedEnvironmentalNotificationMessage> construct_denm_payload(flatbuffers::FlatBufferBuilder &builder, const ros_etsi_its_msgs::msg::DENM::SharedPtr denm) {
    
    // Construct the DENM management container
    auto denm_mgmt_cntr = construct_denm_mgmt_cntnr(builder, denm);

    //Gos_DENMType_enum_t denm_type
    
    // Construct the situation container (Assuming this is similar to how you construct the other containers)
    auto situation_cntnr = construct_situation_cntnr(builder, denm);
    
    // Construct the location container
    //auto location_cntnr = construct_location_cntnr(builder, denm);
    
    // Construct the alacarte container (if applicable)
    //auto alacarte_cntnr = construct_alacarte_cntnr(builder, denm);
    
    // Create the Decentralized Environmental Notification Message (DENM) payload
    // ::flatbuffers::Offset<Gos::DecentralizedEnvironmentalNotificationMessage> denm_payload = Gos::CreateDecentralizedEnvironmentalNotificationMessage(
    //     builder, 
    //     mgmt_cntnr, 
    //     situation_cntnr, 
    //     location_cntnr, 
    //     alacarte_cntnr
    // );
    ::flatbuffers::Offset<Gos::DecentralizedEnvironmentalNotificationMessage> denm_payload = Gos::CreateDecentralizedEnvironmentalNotificationMessage(
        builder, 
        denm_mgmt_cntr,
        situation_cntnr
    );

    return denm_payload;
}

// Implement other necessary functions similar to how CPM was done but tailored for DENM
::flatbuffers::Offset<DenmManagementContainer> construct_denm_mgmt_cntnr(flatbuffers::FlatBufferBuilder &builder, const ros_etsi_its_msgs::msg::DENM::SharedPtr ptr){

    
    //station type
    uint64_t originating_station_id_new = 1; 
    // Action ID (Assuming `action_id` is a complex type with its own FlatBuffers table)
    ::flatbuffers::Offset<ActionID> action_id = Gos::CreateActionID(builder, 
                                                                    originating_station_id_new,
                                                                    ptr->management.action_id.sequence_number);

    // Detection time
    uint64_t detection_time = ptr->management.detection_time;

    // Reference time
    uint64_t reference_time = ptr->management.reference_time;

    // Termination (Assuming this is an enum type and needs casting)
    Gos::Termination termination = static_cast<Gos::Termination>(ptr->management.termination);

    // Event position
    uint32_t semi_major_confidence = 1;
    uint32_t semi_minor_confidence = 2;
    uint32_t semi_major_orientation = 3;
    ::flatbuffers::Offset<Gos::PositionConfidenceEllipse> pos_conf = Gos::CreatePositionConfidenceEllipse(builder,
                                                                                                        semi_major_confidence,  
                                                                                                        semi_minor_confidence,
                                                                                                        semi_major_orientation);
    int32_t value_new = 0;
    uint32_t confidence_dummy = 1;                                                                                                     

    ::flatbuffers::Offset<Gos::Altitude> altitude = Gos::CreateAltitude(builder, value_new, confidence_dummy);
    int32_t lat= 0;
    int32_t lon = 0;
    ::flatbuffers::Offset<ReferencePosition> event_pos = Gos::CreateReferencePosition(builder, 
                                                                                       lat,
                                                                                       lon,
                                                                                       pos_conf, 
                                                                                       altitude);

    // Relevance distance (Enum)
    uint32_t relevent_dist_dummy = 0;
    Gos::RelevanceDistance relevance_distance = static_cast<Gos::RelevanceDistance>(relevent_dist_dummy);

    // Relevance traffic direction (Enum)
    uint32_t relevent_direct_dummy = 0;
    Gos::RelevanceTrafficDirection relevance_traffic_direction = static_cast<Gos::RelevanceTrafficDirection>(relevent_direct_dummy);

    // Validity duration
    uint32_t validity_duration = ptr->management.validity_duration;

    // Transmission interval
    uint32_t transmission_interval = ptr->management.transmission_interval;

    // Station type
    //Gos::StationType stn_type = static_cast<Gos::StationType>(ptr->management.station_type);
    Gos::StationType stn_type = static_cast<Gos::StationType>(ptr->management.station_type.value);
    //auto uint32_t trigger = 1;
    //::flatbuffers::Offset<StationType> station_type_for_inserting = Gos::EnumNameStationType(builder,trigger);

    // ::flatbuffers::Offset<DenmManagementContainer> denm_mgmt_cntr = Gos::CreateDenmManagementContainer(builder, 
    //                                                                                                     action_id, 
    //                                                                                                     detection_time, 
    //                                                                                                     reference_time, 
    //                                                                                                     termination, 
    //                                                                                                     event_pos, 
    //                                                                                                     relevance_distance, 
    //                                                                                                     relevance_traffic_direction, 
    //                                                                                                     validity_duration, 
    //                                                                                                     transmission_interval, 
    //                                                                                                     stn_type);

    //mgmt_cntr = ::flatbuffers::Offset<DenmManagementContainer> 
    ::flatbuffers::Offset<DenmManagementContainer> denm_mgmt_cntr = Gos::CreateDenmManagementContainer(builder,
                                                                                                        action_id, 
                                                                                                        detection_time, 
                                                                                                        reference_time, 
                                                                                                        termination,
                                                                                                        event_pos,
                                                                                                        relevance_distance,
                                                                                                        relevance_traffic_direction,
                                                                                                        validity_duration,
                                                                                                        transmission_interval,
                                                                                                        stn_type
                                                                                                        );


    return denm_mgmt_cntr;
}

