class DenmSendNode : public rclcpp::Node
{
public:
    DenmSendNode() : Node("denm_send_node")
    {
        // Declare and get the parameter "Trigger"
        this->declare_parameter<int>("trigger", 10);  // Default value is 22
        int trigger_denm;
        this->get_parameter("trigger", trigger_denm);
        RCLCPP_INFO(this->get_logger(), "Trigger Set to: %d", trigger_denm);

        // Construct the server address or use a predefined IP adress
        std::string cohda_addr = "192.168.1" + std::to_string(trigger_denm) + ".108";
        server_addr_ = SERVER_ADDR;//cohda_addr;
        std::cout << "SERVER_ADDR: " << server_addr_ << std::endl;

        // Create the DENM message
        auto denm_ = std::make_shared<ros_etsi_its_msgs::msg::DENM>();

        // Fill the DENM message with necessary data
        uint32_t trigger_kodo = static_cast<uint32_t>(trigger_denm);

        denm_->its_header.station_id = 1;
        denm_->its_header.message_id = trigger_kodo;

        if (trigger_kodo == 10) {

            RCLCPP_INFO(this->get_logger(), "Roadwork trigger is successfully sent.");
            printf("DENM with ROADWORKS Warning Sent CAUSE_CODE=3\n");

        } else if (trigger_kodo == 20) {

            RCLCPP_INFO(this->get_logger(), "AC Accident.");
            printf("DENM with Accident Warning Sent CAUSE_CODE=99\n");

        } else if (trigger_kodo == 30) {

            RCLCPP_INFO(this->get_logger(), "Emergency vehicle approaching.");
            printf("DENM with Emergency Vehicle Approaching Warning Sent CAUSE_CODE=95\n");

        } else {

            RCLCPP_INFO(this->get_logger(), "Unknown trigger parameter: %d", trigger_kodo);
        }

        //Start filling Facility layer maessage 
        generateMessage(denm_);

        // Optionally create a timer for periodic tasks
        timer_ = this->create_wall_timer(
            std::chrono::seconds(1),
            [this]() { this->timer_callback(); });
    }

private:
    void generateMessage(const ros_etsi_its_msgs::msg::DENM::SharedPtr denm) {
        // Populate the DENM message here
        // Example:
        // denm->data_field = some_value;
        std::cout << "generateMessage: Generating DENM message..." << std::endl;
        construct_gossip_message(denm);
        std::cout << "generateMessage: DENM message generation complete." << std::endl;
    }

    void timer_callback() {
        // Do something periodically
        RCLCPP_INFO(this->get_logger(), "Timer callback");
    }

    std::string server_addr_;
    //std::string SERVER_ADDR;
    const ros_etsi_its_msgs::msg::DENM::SharedPtr denm;
    rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char * argv[])
{
    rclcpp::init(argc, argv);
    rclcpp::spin(std::make_shared<DenmSendNode>());
    rclcpp::shutdown();
    return 0;
}


